/**
 * Asset Intelligence reality reset (Track v5). This file used to generate
 * an entirely fabricated forestry simulation (seeded pseudo-random growth
 * curves, fake species/DBH/height distributions, fake contractors,
 * invoices and a fake multi-year portfolio-value walk) for the three real
 * reference assets. That entire simulation engine has been removed.
 *
 * Every number reachable from this file now traces to
 * vite-version/src/app/dashboard/data/asset-state-v1.json, generated by
 * backend/scripts/asset_state_model.py -- which reuses the SAME validated
 * hierarchical Monte Carlo engine built for the Zurkt/Evergreen supply
 * case, not a second model. See asset-intelligence-data.ts for the typed
 * AssetState this file is built on top of.
 *
 * `AssetSubBlock` below is now a DERIVED ANALYSIS ZONE (Track v5-4): an
 * illustrative area-weighted split of the asset's real modelled
 * material-class mixture, NOT a surveyed compartment plan. It carries a
 * material class and a real probability -- never a fabricated species,
 * age, DBH, height, contractor, or activity.
 */
import {
  assetStates,
  deriveAnalysisZones,
  formatMaterialClassLabel,
  getAssetStateByEntityId,
  MATERIAL_CLASS_COLORS,
  type AssetState,
  type DerivedAnalysisZone,
} from "./asset-intelligence-data"

export type TreeVariety = string // now a material-class key (e.g. "eucalyptus_plantation") -- see MATERIAL_CLASS_COLORS
export type Country = "Uganda" | "Kenya" | "Tanzania"

export type AssetGeometryTier = "canonical_polygon" | "source_verified_polygon"

export type CanonicalEntityIdentity = {
  entityId: string
  entityType: string
  canonicalName: string
  worldId: string
  geometryObservationId: string
  geometryObservationMethod: string
  aoiId: string
  aoiVersionId: string
  cohortKeys: string[]
  operationalDatabase: string
  confirmedAt: string
}

export type AssetEvidenceProvenance = {
  geometryTier: AssetGeometryTier
  geometryLabel: string
  geometryNote: string
  canonicalIdentity: CanonicalEntityIdentity
  compartmentsNote: string
}

/** A DERIVED ANALYSIS ZONE -- real modelled material-class share, not a surveyed compartment. */
export type AssetSubBlock = {
  id: string
  subBlock: string
  variety: TreeVariety
  size: number
  plantedSize: number
  /** Real probability (0-100) of this material class within the asset, NOT an age in years. */
  age: number
}

export type AssetGroup = {
  id: string
  block: string
  summaryTitle: string
  summaryDescription: string
  location: string
  country: Country
  mapCenter: [number, number]
  provenance: AssetEvidenceProvenance
  subBlocks: AssetSubBlock[]
  /** The real AssetState this group is built from -- consult directly for anything beyond map layout. */
  assetState: AssetState
}

export type SubBlock = AssetSubBlock

export type DerivedAreaMetrics = {
  totalTrees: number
  estimatedVolume: number
  estimatedTonnage: number
  estimatedValuation: number
  investmentPlaced: number
  averageHeight: number
  averageDbh: number
  survivalRate: number
  expectedPricePerTonne: number
  expectedPricePerM3: number
}

export type SpeciesAllocationDatum = {
  category: TreeVariety
  value: number
  amount: number
  fill: string
}

export const dashboardCurrentYear = 2026
const WOOD_DENSITY_T_PER_M3 = 0.55

