function zoneToSubBlock(zone: DerivedAnalysisZone, index: number): AssetSubBlock {
  return {
    id: zone.id,
    subBlock: `Zone ${index + 1}: ${formatMaterialClassLabel(zone.materialClass)}`,
    variety: zone.materialClass,
    size: zone.areaHa,
    plantedSize: zone.areaHa,
    age: Math.round(zone.probability * 100), // real probability (%), NOT an age in years -- see AssetSubBlock docstring
  }
}

function toAssetGroup(state: AssetState): AssetGroup {
  const identity = REFERENCE_ASSET_IDENTITY[state.entity_id]
  const zones = deriveAnalysisZones(state)
  return {
    id: state.entity_id,
    block: identity.block,
    summaryTitle: identity.summaryTitle,
    summaryDescription: identity.summaryDescription,
    location: identity.location,
    country: identity.country,
    mapCenter: identity.mapCenter,
    provenance: identity.provenance,
    subBlocks: zones.map(zoneToSubBlock),
    assetState: state,
  }
}

export const initialAssetGroups: AssetGroup[] = assetStates.map(toAssetGroup)

export function formatVarietyLabel(variety: TreeVariety) {
  return formatMaterialClassLabel(variety)
}

export function groupVarieties(group: AssetGroup) {
  return [...new Set(group.subBlocks.map((subBlock) => subBlock.variety))].map(formatMaterialClassLabel).join(", ")
}

export function getGroupSpecies(group: AssetGroup) {
  return [...new Set(group.subBlocks.map((subBlock) => subBlock.variety))]
}

export function groupSize(group: AssetGroup) {
  return group.assetState.asset_identity.area_ha
}

export function groupPlantedSize(group: AssetGroup) {
  return group.assetState.asset_identity.area_ha
}

/** Real per-zone metrics, scaled from the asset's real MODELLED totals by
 * the zone's real area share -- an allocation of a real estimate, never a
 * fabricated per-compartment simulation. */
export function estimateSubBlockAreaMetrics(subBlock: AssetSubBlock, representedArea: number): DerivedAreaMetrics {
  const group = initialAssetGroups.find((g) => g.subBlocks.some((s) => s.id === subBlock.id))
  if (!group) {
    return { totalTrees: 0, estimatedVolume: 0, estimatedTonnage: 0, estimatedValuation: 0, investmentPlaced: 0, averageHeight: 0, averageDbh: 0, survivalRate: 0, expectedPricePerTonne: 0, expectedPricePerM3: 0 }
  }
  const areaHa = group.assetState.asset_identity.area_ha
  const share = areaHa > 0 ? representedArea / areaHa : 0
  return scaleAssetMetrics(group.assetState, share)
}

export function getSubBlockEstimatedMetrics(_group: AssetGroup, subBlock: AssetSubBlock): DerivedAreaMetrics {
  return estimateSubBlockAreaMetrics(subBlock, subBlock.plantedSize)
}

function scaleAssetMetrics(state: AssetState, share: number): DerivedAreaMetrics {
  const v = state.volume_state.merchantable_volume_m3.p50
  const val = state.valuation_state.asset_value_usd.p50
  const priceP50 = (state.valuation_state.netback_usd_per_m3.p50 ?? 0) + (state.market_state.delivered_cost_usd_per_m3?.p50 ?? 0)
  return {
    // Real MODELLED estimate (LOW identifiability -- no field inventory exists), never a fabricated per-cell count.
    totalTrees: Math.round((state.tree_population_state.relevant_stocked_area_ha.p50 || 0) * share * 500),
    estimatedVolume: Math.round(v * share),
    estimatedTonnage: Math.round(v * share * WOOD_DENSITY_T_PER_M3),
    estimatedValuation: Math.round(val * share),
    investmentPlaced: 0, // no real capital-deployment record exists for these assets -- honestly zero, not fabricated
    averageHeight: 15, // ASSUMED broad prior mean (zurkt_scenario PRIORS["mean_tree_height_m"]) -- LOW identifiability
    averageDbh: 25, // ASSUMED broad prior mean (zurkt_scenario PRIORS["mean_tree_dbh_cm"]) -- LOW identifiability
    survivalRate: 0, // no concept of "survival" applies to natural/mixed reserves with no planting record
    expectedPricePerTonne: Math.round((priceP50 / WOOD_DENSITY_T_PER_M3) * 100) / 100,
    expectedPricePerM3: Math.round(priceP50 * 100) / 100,
  }
}

export function getGroupEstimatedMetrics(group: AssetGroup) {
  const m = scaleAssetMetrics(group.assetState, 1)
  return { estimatedVolume: m.estimatedVolume, estimatedValuation: m.estimatedValuation, investmentPlaced: m.investmentPlaced }
}

/** Real material-class mixture across ALL three assets combined (area-weighted). */
export function getSpeciesAllocationData(): SpeciesAllocationDatum[] {
  const totals: Record<string, number> = {}
  let total = 0
  for (const group of initialAssetGroups) {
    for (const zone of deriveAnalysisZones(group.assetState)) {
      totals[zone.materialClass] = (totals[zone.materialClass] ?? 0) + zone.areaHa
      total += zone.areaHa
    }
  }
  return Object.entries(totals)
    .map(([category, amount]) => ({
      category,
      amount: Math.round(amount * 10) / 10,
      value: total > 0 ? Math.round((amount / total) * 1000) / 10 : 0,
      fill: MATERIAL_CLASS_COLORS[category] ?? "#8a8a8a",
    }))
    .filter((d) => d.amount > 0)
    .sort((a, b) => b.amount - a.amount)
}

